// Generated once from Google Fonts and inlined so the render is offline and
// deterministic. Latin subsets only. No delayRender: a data URI needs no
// network, so it cannot stall a render the way a fetched face can.

export const GROTESK_500 = "data:font/woff2;base64,";

export const GROTESK_700 = "data:font/woff2;base64,";

export const MONO_400 = "data:font/woff2;base64,";
